{
  "name": "pairwise_preference_loss",
  "intuition": "This loss measures the pairwise preference between better and worse samples based on log probabilities, encouraging the model to assign higher likelihood to preferred samples. Using the difference in log_probs with a bias from the cost_gap or advantage signals ensures it aligns with the objective of lowering cost or risk. The pairwise approach helps the model learn fine-grained preference signals directly from comparative data.",
  "pseudocode": "loss = mean( logsigmoid( log_prob_w - log_prob_l + alpha * cost_gap ) )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "score_difference",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch.get(\"cost_gap\", zeros_like(log_prob_w))\n    preference_score = log_prob_w - log_prob_l + alpha * cost_gap\n    loss = ops.mean(ops.logsigmoid(preference_score) * batch[\"weight\"])\n    return loss"
}

{
  "name": "loss_logsigmoid_000_cost_sum",
  "intuition": "rule_based: pairwise logsigmoid loss with sum aggregation",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha*scale*(lpw-lpl) - 0.1*gap, -20, 20)) * weight)",
  "hyperparams": {
    "scale": 1.9496803035382082,
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return ops.sum(loss)"
}

{
  "name": "pairwise_pref_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to preferred sequences by computing a pairwise comparison between preferred (w) and less preferred (l) samples. Using the difference in log probabilities weighted by a cost gap signal emphasizes preferences aligned with cost improvements, helping the model learn to prefer better options directly.",
  "pseudocode": "loss = mean( max(0, logsigmoid(log_prob_w - log_prob_l + alpha * cost_gap)) )",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "preference",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "ranking"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap", "log_prob_w_mean", "log_prob_l_mean"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch.get(\"cost_gap\", zeros_like(log_prob_w))\n    # Compute pairwise preference using logistic sigmoid\n    preference_score = ops.logsigmoid(log_prob_w - log_prob_l + alpha * cost_gap)\n    # Calculate mean as loss (maximize preference_score, so minimize negative)\n    loss = -ops.mean(preference_score)\n    return loss"
}

{
