  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    alpha = float(extra.get('alpha', 1.0))\n    scale = alpha\n    diff = log_prob_w - log_prob_l\n    loss = -ops.logsigmoid(-diff * scale) * cost_gap\n    return ops.mean(loss)"
