{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to lower-cost sequences by penalizing pairs where the cost gap is large and the log probability of the worse sequence is higher. Using logsigmoid on the negative cost gap aligns the optimization towards minimizing cost differences, effectively promoting better solutions. The pairwise structure ensures direct comparison between sequences in each pair, enhancing preference modeling.",
  "pseudocode": "loss = mean over pairs of (-logsigmoid(-(log_prob_w - log_prob_l) * scale) * clamp(cost_gap, min=eps))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    zeros = log_prob_w.new_zeros(log_prob_w.shape)\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', zeros) - batch.get('cost_a', zeros))\n    cost_gap = ops.clamp(cost_gap, min=eps)\n    weight = batch.get('weight', log_prob_w.new_ones(log_prob_w.shape))\n    alpha = float(extra.get('alpha', 1.0))\n    scale = alpha\n    diff = log_prob_w - log_prob_l\n    loss = -ops.logsigmoid(-diff * scale) * cost_gap\n    weighted_loss = loss * weight\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_softplus_margin",
  "intuition": "This loss applies a softplus function to the weighted difference of log probabilities, incorporating a learned margin based on advantage and rank signals. The softplus ensures smooth, differentiable margins that help the model better distinguish preferred pairs without harsh clipping, promoting stable gradient flows and diverse preference learning signals.",
  "pseudocode": "x = alpha * (log_prob_w - log_prob_l) - (advantage_signal + rank_signal)\nloss = softplus(x) * weight\nreturn loss.mean()",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_rank",
    "link_family": "softplus_margin",
    "agg_family": "mean",
    "constraint_family": "smooth"
  },
  "operators_used": ["logsigmoid", "softplus"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "delta_z"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_w = batch['advantage_w']\n    delta_z = batch['delta_z']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', 1.0))\n\n    margin_signal = advantage_w + delta_z\n    x = alpha * (lpw - lpl) - margin_signal\n    loss = ops.softplus(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

