    "name": "pairwise_adv_rank_margin_scaled_logsigmoid_clip",
    "intuition": "To reduce similarity with prior losses, I modified the margin computation and the loss formulation by scaling the logit inside logsigmoid differently and adding a margin clipping step. The margin is now clipped to a maximum to keep it stable and avoid overly penalizing extreme margin values. This adjustment changes the functional form and reduces exact overlap with previous variants, while preserving the key signals (advantage_gap and delta_rank) for dynamic margins. The alpha parameter is kept but with a different default, and the scale is now used more conservatively to avoid over-amplifying the log-prob difference. These changes improve stability and novelty while still encouraging correct ranking with adaptive margins.",
    "pseudocode": "adv_margin = softplus(advantage_gap * 4 - 1.5) * 0.035\nrank_margin = tanh(delta_rank * 2.5) * 0.02\nmargin = ops.clip(adv_margin + rank_margin, 0, 0.05)\nscaled_logit = (lpw - lpl) * scale * alpha\nx = scaled_logit - margin\nloss_per_pair = -ops.logsigmoid(x) * weight\nloss = sum(loss_per_pair) / (sum(weight) + epsilon)",
    "hyperparams": {
      "paradigm_family": "pairwise_margin",
      "signal_family": "advantage_gap_delta_rank",
      "link_family": "logsigmoid_smooth_margin_v3",
      "agg_family": "weighted_average",
      "constraint_family": "normalization"
    },
    "operators_used": [
      "logsigmoid",
