        "advantage_gap",
        "delta_rank"
      ],
      "returns": "scalar",
      "mode": "pairwise"
    },
    "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_gap = batch['advantage_gap']\n    delta_rank = batch['delta_rank']\n    weight = batch['weight']\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 0.8)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n\n    adv_margin = ops.softplus(advantage_gap * 4.0 - 1.5) * 0.035\n    rank_margin = ops.tanh(delta_rank * 2.5) * 0.02\n    margin = ops.clip(adv_margin + rank_margin, 0.0, 0.05)\n\n    scaled_logit = (lpw - lpl) * scale * alpha\n    x = scaled_logit - margin\n\n    loss_per_pair = -ops.logsigmoid(x) * weight\n    denom = ops.sum(weight) + 1e-8\n    return ops.sum(loss_per_pair) / denom"
  }
