  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_gap = batch['advantage_gap']\n    delta_rank = batch['delta_rank']\n    weight = batch['weight']\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.2))\n    margin_adv = float(extra.get('hyperparams', {}).get('margin_adv', 0.03))\n    margin_rank = float(extra.get('hyperparams', {}).get('margin_rank', 0.04))\n\n    adv_factor = margin_adv * ops.exp(-ops.relu(-advantage_gap) * 5)\n    rank_factor = margin_rank * (ops.tanh(delta_rank * 3) + 1.0) * 0.5\n    margin = adv_factor * rank_factor\n\n    x_raw = alpha * scale * (lpw - lpl) - margin\n    x_clipped = ops.clip(x_raw, -5.0, 5.0)\n\n    loss_vec = -ops.logsigmoid(x_clipped)\n    if weight is not None:\n        loss_vec = loss_vec * weight\n\n    loss = loss_vec.sum() / (ops.sum(weight) + 1e-12)\n    return loss"
